head.script:
scwin.checkEl = function(id1, id2) {
    if (WebSquare.wUnit.getDomById($p.id + id1)) {
        return true;
    } else if (WebSquare.wUnit.getDomById($p.id + id2)) {
        return true;
    }
    return false;
}
scwin.checktype1 = function() {
    return typeof wfm1;
}
scwin.checktype2 = function() {
    return typeof WebSquare.wUnit.getDomById('wfm1_selectbox1');
}
scwin.checktype3 = function() {
    return typeof WebSquare.wUnit.getDomById('wfm1_input1');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 setRowPosition(0); API 가 추가되었는지 확인한다.
    //1. In the Source tab, setRowPosition (0); Make sure the API has been added.
    //Verify step 1. dataList.setRowPosition(0); API
    //1. dataList.setRowPosition (0); API
    //Test step 2. 브라우저에서 main.xml 을 실행한다.
    //2. Run main.xml in your browser.
    //Verify step 2. wframe 화면이 정상적으로 나온다. 
    //2. The wframe screen appears normally.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype1()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('wfm1_wq_uuid_12','wq_uuid_12')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype3()", "object");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Mar-2018
    //end
    // wfm1.setSrc("wfrm_sub.xml");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
